class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False

        target = total // 2

        # dp[j] 表示能否选出和为 j 的子集
        dp = [False] * (target + 1)
        dp[0] = True  # 和为0总是可以

        for num in nums:
            # 必须从大到小遍历，避免重复使用同一个数
            for j in range(target, num - 1, -1):
                if dp[j - num]:
                    dp[j] = True

            # 提前结束
            if dp[target]:
                return True

        return dp[target]
